@push('scripts')<script>const pts=@json($mapPoints);const map=L.map('shipment-map').setView(pts.length?[pts[0].lat,pts[0].lng]:[-2.5,118],pts.length?5:4);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors'}).addTo(map);pts.forEach(p=>L.marker([p.lat,p.lng]).addTo(map).bindPopup(p.name));if(pts.length>1)map.fitBounds(pts.map(p=>[p.lat,p.lng]),{padding:[25,25]});</script>@endpush
